input.content:
'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'true'

  cookieStore.set(NOTIFICATIONS_COOKIE, String(!enabled))

  refresh()
}

